# Try counting horizontal neighbors to the left/right that aren't 6
grid = [
    [1, 6, 6, 6, 6, 6, 5, 6],
    [7, 3, 6, 7, 3, 6, 5, 6],
    [6, 6, 6, 6, 6, 6, 5, 1],
    [6, 4, 6, 5, 6, 6, 6, 6],
    [3, 4, 6, 4, 7, 1, 5, 6],
    [6, 5, 6, 3, 6, 6, 6, 5],
    [4, 3, 6, 6, 6, 6, 6, 6],
    [6, 4, 6, 4, 6, 5, 1, 1]
]

rows, cols = len(grid), len(grid[0])

def count_left_non6(r, c):
    return sum(1 for col_idx in range(c) if grid[r][col_idx] != 6)

def count_right_non6(r, c):
    return sum(1 for col_idx in range(c+1, cols) if grid[r][col_idx] != 6)

print("Testing horizontal counts:")
for r in range(rows):
    row_result = [(count_left_non6(r,c), count_right_non6(r,c)) for c in range(cols)]
    print(f"Row {r}: {row_result}")

# Try counting total neighbors (all 8 directions) for each cell that is 6
grid = [
    [1, 6, 6, 6, 6, 6, 5, 6],
    [7, 3, 6, 7, 3, 6, 5, 6],
    [6, 6, 6, 6, 6, 6, 5, 1],
    [6, 4, 6, 5, 6, 6, 6, 6],
    [3, 4, 6, 4, 7, 1, 5, 6],
    [6, 5, 6, 3, 6, 6, 6, 5],
    [4, 3, 6, 6, 6, 6, 6, 6],
    [6, 4, 6, 4, 6, 5, 1, 1]
]

rows, cols = 8, 8

def count_non6_neighbors(r, c):
    count = 0
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] != 6:
                    count += 1
    return count

result = []
for r in range(rows):
    row_result = []
    for c in range(cols):
        if grid[r][c] == 6:
            row_result.append(count_non6_neighbors(r, c))
        else:
            row_result.append(0)
    result.append(row_result)

print("Count of non-6 neighbors for each 6-cell:")
for row in result:
    print(row)

# Try counting unique adjacent (including diagonal) pairs for each cell
grid = [
    [1, 6, 6, 6, 6, 6, 5, 6],
    [7, 3, 6, 7, 3, 6, 5, 6],
    [6, 6, 6, 6, 6, 6, 5, 1],
    [6, 4, 6, 5, 6, 6, 6, 6],
    [3, 4, 6, 4, 7, 1, 5, 6],
    [6, 5, 6, 3, 6, 6, 6, 5],
    [4, 3, 6, 6, 6, 6, 6, 6],
    [6, 4, 6, 4, 6, 5, 1, 1]
]

def count_unique_neighbors(grid, r, c):
    seen = set()
    rows, cols = len(grid), len(grid[0])
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                seen.add((dr, dc))  # Just direction count
    return len(seen)

# All cells should have 8 neighbors except edges/corners
# Try counting actual neighbor VALUES instead
def count_unique_neighbor_values(grid, r, c):
    seen = set()
    rows, cols = len(grid), len(grid[0])
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                seen.add(grid[nr][nc])
    return len(seen)

unique_neighbor_vals = [[count_unique_neighbor_values(grid, r, c) for c in range(cols)] for r in range(rows)]
print("Unique neighbor values:")
for row in unique_neighbor_vals:
    print(row)

